def meta(title, description, path, kind='website'):
    absolute=f'{PUBLIC_ORIGIN}{path}'
    return f'''<title>{esc(title)} · FIKER</title><meta name="description" content="{esc(description)}"><meta property="og:type" content="{kind}"><meta property="og:site_name" content="FIKER"><meta property="og:title" content="{esc(title)} · FIKER"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{esc(absolute)}"><meta property="og:image" content="/assets/fiker-mark-reference.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)} · FIKER"><meta name="twitter:description" content="{esc(description)}"><link rel="canonical" href="{esc(absolute)}">'''

def page(title, description, path, body, active='', extra_head='', extra_scripts=''):
    org={"@context":"https://schema.org","@type":"Organization","name":"Foundation for Innovative Knowledge & Educational Reform","alternateName":"FIKER","url":"https://fiker.org/","logo":"/assets/fiker-mark-reference.png","sameAs":["https://www.facebook.com/p/FIKER-61576726776400/","https://pk.linkedin.com/company/fikerorg","https://www.instagram.com/fikerorg/"],"knowsAbout":["child rights","child protection","education","youth development","climate action","community development"]}
    schema=f'<script type="application/ld+json">{json.dumps(org,ensure_ascii=False)}</script>'
    if path.startswith('/stories/') and path != '/stories/':
        article={"@context":"https://schema.org","@type":"Article","headline":title,"description":description,"mainEntityOfPage":f'{PUBLIC_ORIGIN}{path}',"author":{"@type":"Organization","name":"FIKER"},"publisher":{"@type":"Organization","name":"FIKER","logo":{"@type":"ImageObject","url":"/assets/fiker-mark-reference.png"}}}
        schema+=f'<script type="application/ld+json">{json.dumps(article,ensure_ascii=False)}</script>'
    hero_image=PAGE_HERO_IMAGES.get(path,'fiker04.webp')
    if '<section class="page-hero">' in body:
        body=body.replace('<section class="page-hero">', f'<section class="page-hero" style="--page-hero-image:url(\'/assets/{hero_image}\')">', 1)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">{meta(title,description,path)}{schema}{extra_head}<link rel="icon" href="/assets/fiker-mark-reference.png"><link rel="stylesheet" href="/styles/tokens.css"><link rel="stylesheet" href="/styles/site.css"></head><body>{header(active)}<main id="main">{body}</main>{footer()}{scripts(extra_scripts)}</body></html>'''

def eyebrow(text): return f'<p class="eyebrow">{esc(text)}</p>'
def arrow(): return '<span class="arrow" aria-hidden="true">↗</span>'
def button(text, href, cls='button-primary'): return f'<a class="button {cls}" href="{href}">{text} {arrow()}</a>'
def section_head(kicker, title, copy='', link=''):
    link_html = f'<a class="text-link" href="{link}">View all {arrow()}</a>' if link else ''
    image=SECTION_IMAGES.get(kicker)
    media=f'<div class="section-head-media"><img src="/assets/{image}" alt="" loading="lazy"></div>' if image else ''
    return f'<div class="section-head {"section-head-with-image" if image else ""}">{media}{eyebrow(kicker)}<h2>{title}</h2>{f"<p>{copy}</p>" if copy else ""}{link_html}</div>'

def image_style(filename, position='center'):
    return f'style="background-image:linear-gradient(90deg,rgba(11,38,34,.82) 0%,rgba(11,38,34,.28) 52%,rgba(11,38,34,.05) 100%),url(\'/assets/{esc(filename)}\');background-position:{position}"'

