def project_cards(items=None):
    items = items or projects[:4]
    return ''.join(f'''<article class="project-card reveal" data-category="{esc(p['category'])}" data-search="{esc(p['title']+' '+p['location']+' '+p['category'])}"><div class="project-visual" {image_style(p.get('image','fiker01.webp'))}><span class="visual-label">{esc(p['category'])}</span><span class="visual-glyph">{p['category'][0]}</span></div><div class="project-content"><div class="meta-row"><span>{esc(p['location'])}</span><span>{esc(p['date'])}</span></div><h3>{esc(p['title'])}</h3><p>{esc(p['description'])}</p><div class="card-footer"><span class="status-chip">{esc(p['status'])}</span><a class="text-link" href="/projects/{p['slug']}/">View record {arrow()}</a></div></div></article>''' for p in items)

def story_cards(items=None):
    items = items or stories
    return ''.join(f'''<article class="story-card reveal" data-category="{esc(p['category'])}" data-search="{esc(p['title']+' '+p['description'])}" style="--story-image:url('/assets/{esc(p.get('image','fiker01.webp'))}')"><div class="story-index">{str(items.index(p)+1).zfill(2)}</div><div><span class="story-tag">{esc(p['tag'])} · {esc(p['category'])}</span><h3>{esc(p['title'])}</h3><p>{esc(p['description'])}</p><div class="meta-row"><span>{esc(p['date'])}</span><span>{esc(p['reading'])}</span></div></div><a class="story-arrow" href="/stories/{p['slug']}/" aria-label="Read {esc(p['title'])}">{arrow()}</a></article>''' for p in items)

