        return '''<div class="field-grid"><label>Full name<input required name="name" autocomplete="name" placeholder="Your name"></label><label>Email<input required type="email" name="email" autocomplete="email" placeholder="you@example.org"></label></div><div class="field-grid"><label>Phone<input name="phone" autocomplete="tel" placeholder="Optional"></label><label>City / district<input name="city" placeholder="e.g. Gilgit"></label></div><label>Area of interest<select required name="interest"><option value="">Select one</option><option>Child Protection</option><option>Education &amp; Literacy</option><option>Climate &amp; Environment</option><option>Youth Development</option><option>Community Outreach</option><option>Digital Media / Design</option><option>Research / Events</option></select></label><label>Skills and experience<textarea name="skills" rows="3" placeholder="Tell us what you can contribute"></textarea></label><label>Availability<textarea name="availability" rows="2" placeholder="When and how would you like to help?"></textarea></label><label>Message<textarea name="message" rows="4" placeholder="Anything else FIKER should know?"></textarea></label>'''
