def protection(sub=''):
    if sub=='rights': title='Know your rights'; lead='Clear, age-appropriate information helps children and young people understand that safety, dignity and respect are rights.'; content='Every child deserves to be listened to, treated with respect and protected from abuse, exploitation, violence and neglect. FIKER should adapt this page with approved local-language resources, legal information and safe referral routes.'; active='Child Protection'
    elif sub=='staying-safe': title='Staying safe'; lead='Small, clear conversations about boundaries, trusted adults and uncomfortable situations can help children feel more confident.'; content='Use calm language. If something feels wrong, you can say no, move away when it is safe, tell a trusted adult and keep asking for help. FIKER must review all child-facing language with safeguarding specialists before publication.'; active='Child Protection'
    elif sub=='online-safety': title='Online safety'; lead='Digital spaces can be useful, creative and social. They also need boundaries, privacy and support.'; content='Protect passwords, think before sharing personal information, use privacy settings, block or report harmful behavior and talk to a trusted adult if someone pressures, threatens or tries to isolate you. This is educational information, not a substitute for verified support.'; active='Child Protection'
    else: title='Child protection'; lead='A calm place to learn about rights, safety and trusted support.'; content='FIKER’s child-protection section should help children, young people, parents and teachers talk about safety without fear or shame. It should make practical information easy to find and keep emergency and referral details verified.'; active='Child Protection'
    return page(title,lead,f'/protection/{sub+"/" if sub else ""}',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Child protection</span>{f'<span>/</span><span>{esc(title)}</span>' if sub else ''}</div>{eyebrow('Child protection')}<h1>{esc(title)}</h1><p>{esc(lead)}</p></div></section><section class="section"><div class="shell content-grid"><div class="prose"><p class="intro-lede">{esc(content)}</p><h2>Keep the conversation practical</h2><p>Use examples that respect dignity and do not show graphic violence or traumatic imagery. Avoid asking children to share more personal information than is needed. Make it clear when a resource is a draft, when a contact has not been verified and what a person can expect next.</p><div class="accordion"><div class="accordion-item"><button class="accordion-button" aria-expanded="false">Good touch / bad touch conversations <span>+</span></button><div class="accordion-panel">Teach body autonomy, boundaries, trusted adults and the right to say no in age-appropriate language. FIKER should review this content with safeguarding professionals and local partners.</div></div><div class="accordion-item"><button class="accordion-button" aria-expanded="false">Bullying and cyberbullying <span>+</span></button><div class="accordion-panel">Name what bullying can look like, encourage safe documentation and make it clear that the person experiencing harm is not to blame.</div></div><div class="accordion-item"><button class="accordion-button" aria-expanded="false">Abuse and exploitation <span>+</span></button><div class="accordion-panel">Provide a clear path to an approved safeguarding contact. Do not publish unverified helplines or promise absolute confidentiality.</div></div><div class="accordion-item"><button class="accordion-button" aria-expanded="false">Parent and teacher resources <span>+</span></button><div class="accordion-panel">Create practical conversation guides, signs to pay attention to, referral steps and safe documentation after expert review.</div></div></div><h2>Explore this section</h2><div class="mini-list"><a href="/protection/rights/">Know your rights {arrow()}</a><a href="/protection/staying-safe/">Staying safe {arrow()}</a><a href="/protection/online-safety/">Online safety {arrow()}</a><a href="/protection/help/">I need help {arrow()}</a></div></div><aside class="side-note"><h3>Designed to be calm.</h3><p>Child protection pages should feel trustworthy, age-appropriate and clear. No frightening imagery. No invented emergency details.</p>{button('I need help','/protection/help/','button-help')}</aside></div></section>''',active)


def help_page():
    return page('I need help','A safe, careful place to explain what you need, with clear limits on this frontend prototype.','/protection/help/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/protection/">Child protection</a><span>/</span><span>I need help</span></div>{eyebrow('I need help')}<h1>You do not have to carry this alone.</h1><p>Choose the kind of support you are looking for. This preview does not send reports or provide emergency response.</p></div></section><section class="section"><div class="shell"><div class="safety-panel"><h2>Are you in immediate danger?</h2><p>If someone is in immediate danger, use a verified local emergency service or contact a trusted adult now. FIKER must confirm its official emergency directory before publishing numbers or referral instructions.</p></div><div class="help-grid" style="margin-top:28px"><button class="help-option" type="button" data-help-option="contact"><span class="eyebrow">Option 01</span><h3>I want someone to contact me</h3><p>For a future reviewed workflow where FIKER can confirm who responds, when and how.</p></button><button class="help-option" type="button" data-help-option="anonymous"><span class="eyebrow">Option 02</span><h3>I want to report anonymously</h3><p>For a future reviewed workflow with clear limits, safeguarding escalation and safe data retention.</p></button></div><form class="form-shell" data-demo-form data-help-form hidden style="max-width:760px;margin-top:28px"><input type="hidden" name="submissionType"><h2 data-help-heading>Request a call back</h2><p class="muted">Keep details minimal. Do not include names, exact addresses or anything that could identify a child in this prototype.</p><label>What is happening?<textarea required name="description" rows="5" placeholder="A short description"></textarea></label><div class="field-grid"><label>Where is this happening? <span class="muted">optional</span><input name="location" placeholder="District or general area"></label><label>Is this happening right now?<select name="now"><option>No / not sure</option><option>Yes</option></select></label></div><label>Safe contact method <span class="muted">optional</span><input name="safeContact" placeholder="Only if it is safe to use"></label><label class="checkbox-row"><input type="checkbox" required> I understand this prototype does not promise absolute confidentiality or emergency response.</label><button class="button button-help" type="submit">Save demo state {arrow()}</button><div class="form-status" role="status"></div></form></div></section>''','Child Protection')


