def gallery():
    items=[('MUHAFIZ campaign reference','Campaign reference · approval pending','', 'Awareness sessions','fiker08.webp'),('Community learning visual','Children learning together · approval pending','alt', 'School activities','fiker01.webp'),('School engagement','School-based learning activity · approval pending','blue', 'School activities','fiker03.webp'),('Youth and mentor activity','Youth development visual · approval pending','', 'Team','fiker02.webp'),('Community meeting','Community participation visual · approval pending','alt', 'Community work','fiker07.webp'),('Education workshop','Learning activity · approval pending','blue', 'Workshops','fiker05.webp'),('Girls learning session','Education activity · approval pending','', 'School activities','fiker06.webp'),('MUHAFIZ protection poster','Campaign poster · source reference','alt', 'Awareness sessions','fiker09.webp'),('Partnership meeting','Public engagement reference · approval pending','blue', 'Team','fiker04.webp')]
    cards=''.join(f"<button class=\"gallery-item\" type=\"button\" data-gallery-open data-gallery-index=\"{i}\" data-category=\"{category}\" data-search=\"{title} {caption}\" data-gallery-title=\"{esc(title)}\" data-gallery-tone=\"{tone}\" style=\"--gallery-image:url(\'/assets/{image}\')\"><div class=\"gallery-art {tone}\"></div><div class=\"gallery-caption\">{esc(title)}<small>{esc(caption)}</small></div></button>" for i,(title,caption,tone,category,image) in enumerate(items))
    filters=''.join(f'<button class="filter-btn {"is-active" if i==0 else ""}" type="button" data-filter="{x}">{"All" if i==0 else x.title()}</button>' for i,x in enumerate(['all','School activities','Awareness sessions','Community work','Team']))
    return page('Gallery','A rights-aware visual library for FIKER activities, stories, events and team moments.','/gallery/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Gallery</span></div>{eyebrow('Gallery')}<h1>Show the work with care.</h1><p>Every image should have a caption, date, association, ownership record and consent status before publication.</p></div></section><section class="section"><div class="shell"><div class="filter-bar" data-filter-target=".gallery-item"><div class="pill-row">{filters}</div><span class="result-count" data-count></span></div><div class="gallery-grid">{cards}</div><p class="empty-state" data-empty hidden>No gallery items match that filter yet.</p></div></section><div class="lightbox" role="dialog" aria-modal="true" aria-label="Gallery preview"><button class="lightbox-close" type="button" aria-label="Close gallery preview">×</button><div class="lightbox-card"><div class="lightbox-art"></div><div class="lightbox-nav"><button type="button" data-gallery-prev aria-label="Previous gallery item">←</button><button type="button" data-gallery-next aria-label="Next gallery item">→</button></div><h3 data-lightbox-title>Gallery item</h3><p class="muted">Caption and rights status should be attached to every approved item.</p></div></div>''','')


def resources_page():
    categories=['all']+sorted({r['category'] for r in resources})
    filters=''.join(f'<button class="filter-btn {"is-active" if c=="all" else ""}" type="button" data-filter="{c}">{"All resources" if c=="all" else c}</button>' for c in categories)
    cards=''.join(f'<article class="path-card reveal" data-category="{esc(r["category"])}" data-search="{esc(r["title"]+" "+r["audience"]+" "+r["category"])}"><div><span class="story-tag">{esc(r["type"])} · {esc(r["category"])}</span><h3>{esc(r["title"])}</h3><p>{esc(r["audience"])}<br>{esc(r["status"])}</p></div><span class="text-link">Open resource {arrow()}</span></article>' for r in resources)
    return page('Resources','A carefully labeled library for child safety, youth development, careers, education, climate, digital safety and GB community resources.','/resources/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Resources</span></div>{eyebrow('Resources')}<h1>Useful information, clearly labeled.</h1><p>Each resource should show its format, audience, language, date, source and approval status.</p></div></section><section class="section"><div class="shell"><div class="filter-bar" data-filter-target=".path-card"><input data-search type="search" placeholder="Search resources" aria-label="Search resources"><div class="pill-row">{filters}</div><span class="result-count" data-count></span></div><div class="path-grid">{cards}</div><p class="empty-state" data-empty hidden>No resources match that search yet.</p></div></section>''','')


def volunteer():
    return page('Volunteer with FIKER','Find a clear, safe and accountable way to contribute your time, skills and care.','/volunteer/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Volunteer</span></div>{eyebrow('Get involved')}<h1>Bring your time, skills and care.</h1><p>Volunteer pathways can include child protection, education, climate, youth development, community outreach, media, design, technology, research and events.</p></div></section><section class="section"><div class="shell form-layout"><div class="prose"><p class="intro-lede">A volunteer platform should make expectations clear before it asks for commitment.</p><h2>What to expect</h2><p>FIKER can add current opportunities, eligibility, orientation, location or remote options, time commitment, supervision, safeguarding expectations and what happens after an application.</p><div class="pill-row"><span class="pill">Child Protection</span><span class="pill">Education</span><span class="pill">Climate</span><span class="pill">Youth Development</span><span class="pill">Digital Media</span><span class="pill">Research</span></div>{safety_notice()}</div><form class="form-shell" data-demo-form><h2>Share your interest</h2><p class="muted">This prototype does not send your details.</p>{form_fields('volunteer')}<label class="checkbox-row"><input type="checkbox" required> I understand FIKER should confirm its volunteer screening and safeguarding process before accepting applications.</label><button class="button button-primary" type="submit">Save demo application {arrow()}</button><div class="form-status" role="status"></div></form></div></section>''','Volunteer')


def contact():
    return page('Contact FIKER','Contact FIKER about programs, partnerships, youth participation, volunteering or verified website content.','/contact/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Contact</span></div>{eyebrow('Contact')}<h1>Start a useful conversation.</h1><p>Reach out about programs, schools, partnerships, volunteer opportunities, youth ideas or the information FIKER should verify for this website.</p></div></section><section class="section"><div class="shell form-layout"><form class="form-shell" data-demo-form><h2>Send a message</h2><p class="muted">This prototype does not send your details.</p>{form_fields('contact')}<button class="button button-primary" type="submit">Save demo message {arrow()}</button><div class="form-status" role="status"></div></form><div class="prose"><h2>Official contact details pending</h2><p>FIKER should confirm its official email, phone, office/location, hours, map, social profiles and preferred contact route before this page goes live.</p><div class="notice"><strong>For urgent safety concerns</strong><p>Do not use this prototype as an emergency channel. Use a verified local emergency service or trusted adult. FIKER must approve and publish its referral directory before launch.</p></div><h2>What can be updated here</h2><div class="mini-list"><a href="/work/">Programs and partnerships {arrow()}</a><a href="/volunteer/">Volunteer opportunities {arrow()}</a><a href="/resources/">Resources and verified links {arrow()}</a></div></div></div></section>''','')


def legal(title, kind):
    return page(title,f'{title} placeholder for FIKER pending legal and organizational review.',f'/{kind}/',f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>{esc(title)}</span></div>{eyebrow('Review required')}<h1>{esc(title)}</h1><p>This page is a visible placeholder so the future site has the right architecture from the start.</p></div></section><section class="section"><div class="shell content-grid"><div class="prose"><p class="intro-lede">FIKER should publish an approved {title.lower()} before production launch.</p><h2>What belongs here</h2><p>Include clear language about data collection, consent, cookies, forms, child-safety submissions, retention, third-party services, image permissions, accessibility and how people can ask questions or raise concerns.</p><p>Do not treat this placeholder as legal advice or as a final organizational policy.</p></div><aside class="side-note"><h3>Owner</h3><p>FIKER’s responsible legal, safeguarding or organizational lead should review and approve this content.</p>{button('Contact the team','/contact/','button-primary')}</aside></div></section>''')

pages = {'/':home(),'/about/':about(),'/work/':work_overview(),'/youth/':youth(),'/youth/forum/':forum(),'/protection/':protection(),'/protection/rights/':protection('rights'),'/protection/staying-safe/':protection('staying-safe'),'/protection/online-safety/':protection('online-safety'),'/protection/help/':help_page(),'/projects/':projects_page(),'/events/':events_page(),'/stories/':stories_page(),'/gallery/':gallery(),'/resources/':resources_page(),'/volunteer/':volunteer(),'/contact/':contact(),'/privacy/':legal('Privacy','privacy'),'/terms/':legal('Terms','terms')}
pages['/admin/forum/'] = admin_forum()
for p in programs: pages[f"/work/{p['slug']}/"] = program_detail(p['slug'])
for p in projects: pages[f"/projects/{p['slug']}/"] = project_detail(p['slug'])
for s in stories: pages[f"/stories/{s['slug']}/"] = story_detail(s['slug'])

for route, html in pages.items():
    out = ROOT / route.strip('/') / 'index.html' if route != '/' else ROOT / 'index.html'
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(html, encoding='utf-8')

(ROOT/'styles').mkdir(exist_ok=True); (ROOT/'scripts').mkdir(exist_ok=True); (ROOT/'data').mkdir(exist_ok=True); (ROOT/'partials').mkdir(exist_ok=True)
(ROOT/'styles/tokens.css').write_text(TOKENS, encoding='utf-8')
(ROOT/'styles/site.css').write_text(CSS + '\n[data-empty][hidden]{display:none!important}.chain-progress{position:absolute;left:0;right:0;top:0;height:4px;background:rgba(255,255,255,.12);z-index:5}.chain-progress span{display:block;height:100%;width:100%;background:var(--coral);transform:scaleX(0);transform-origin:left;transition:transform .15s linear}.lightbox-nav{display:flex;justify-content:space-between;margin:14px 0}.lightbox-nav button{border:1px solid var(--line);background:transparent;color:var(--forest);border-radius:999px;width:42px;height:38px;font-size:18px}.checkbox-row{display:flex!important;grid-template-columns:none!important;align-items:flex-start;gap:9px}.checkbox-row input{width:auto;min-height:18px;margin-top:3px}', encoding='utf-8')
(ROOT/'scripts/site.js').write_text(JS, encoding='utf-8')
(ROOT/'scripts/chains.js').write_text(CHAIN_JS, encoding='utf-8')
(ROOT/'data/content.js').write_text(DATA_JS, encoding='utf-8')

routes = [{'path':route,'title':('Home' if route=='/' else route.strip('/').replace('/',' · ').replace('-',' ').title())} for route in pages]
(ROOT/'public/manus-routes.json').write_text(json.dumps({'routes':routes},ensure_ascii=False,indent=2), encoding='utf-8')

sitemap_urls = '\n'.join(f'  <url><loc>{PUBLIC_ORIGIN}{route}</loc></url>' for route in pages)
(ROOT/'public/sitemap.xml').write_text(f'''<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n{sitemap_urls}\n</urlset>''', encoding='utf-8')
(ROOT/'public/robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /admin/\nSitemap: /sitemap.xml\n', encoding='utf-8')

# Project metadata placeholder is intentionally absent until a durable project logo URL is available.
